package com.order.management.paymentservice.model;
import com.order.management.common.constant.PaymentType;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Getter @NoArgsConstructor @Table(name="payment_transaction", indexes=@Index(name="idx_payment_order_status",columnList="orderId,status"), uniqueConstraints=@UniqueConstraint(name="uk_payment_idempotency",columnNames="idempotencyKey"))
public class PaymentTransaction { @Id private UUID id=UUID.randomUUID(); @Column(nullable=false) private UUID orderId; @Column(nullable=false,length=100) private String idempotencyKey; @Column(nullable=false) private double amount; @Enumerated(EnumType.STRING) private PaymentType paymentType; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus status=PaymentStatus.PENDING; @Column(nullable=false) private Instant createdAt=Instant.now(); private Instant completedAt; public PaymentTransaction(UUID orderId,String key,double amount,PaymentType type){this.orderId=orderId;idempotencyKey=key;this.amount=amount;paymentType=type;} public void succeed(){status=PaymentStatus.SUCCEEDED;completedAt=Instant.now();} public void fail(){status=PaymentStatus.FAILED;completedAt=Instant.now();} }
